question:
What is the output of the following C code?

int a[] = {5, 10, 15, 20, 25};
int *p = a + 1;
int x = *p++;
int y = *(p + 1);
int z = ++*p;
printf("%d %d %d", x, y, z);

What is the output of the following C code?

#define CUBE(x) x * x * x
int main() {
    int a = 2;
    printf("%d", CUBE(a + 1));
    return 0;
}

What is the output of the following C code?

int f(void) {
    static int n = 1;
    n = n * 2;
    return n;
}
int main() {
    int s = 0, i;
    for (i = 0; i < 3; i++)
        s = s + f();
    printf("%d", s);
    return 0;
}
